urlset:
{{- range (where .Data.Pages "Section" "!=" "gallery") -}}
    {{- $page := . -}}


            {{- .Permalink -}}

        {{- if not .Lastmod.IsZero -}}

                {{- .Lastmod.Format "2006-01-02T15:04:05-07:00" -}}

        {{- end -}}

        {{- range .Params.images -}}
            {{- with dict "Path" . "Resources" $page.Resources | partial "function/resource.html" -}}

                    {{ .Permalink }}

            {{- end -}}
        {{- end -}}

        {{- if .IsTranslated -}}
            {{- range .Translations -}}

            {{- end -}}

        {{- end -}}

{{- end -}}
